    CHROME, "--headless=new", f"--remote-debugging-port={PORT}", f"--user-data-dir={PROFILE}",
    "--no-first-run", "--no-default-browser-check", "--disable-gpu", "--hide-scrollbars",
    "--window-size=1400,1600", "about:blank",
], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

def wait_ws():
    for _ in range(80):
        try:
            with urllib.request.urlopen(f"http://127.0.0.1:{PORT}/json/version", timeout=1) as r:
                return json.load(r)
        except Exception:
            time.sleep(0.25)
    raise RuntimeError("chrome did not start")

async def main():
    info = wait_ws()
    with urllib.request.urlopen(f"http://127.0.0.1:{PORT}/json/new?about:blank", method="PUT") as r:
        target = json.load(r)
    ws_url = target["webSocketDebuggerUrl"]
    out = {"browser": info["Browser"], "requests": []}
    async with websockets.connect(ws_url, max_size=40_000_000) as ws:
        mid = 0
        pending = {}
        events = []

        async def send(method, params=None):
            nonlocal mid
            mid += 1
            await ws.send(json.dumps({"id": mid, "method": method, "params": params or {}}))
            while True:
                msg = json.loads(await ws.recv())
                if msg.get("id") == mid:
                    if "error" in msg:
                        raise RuntimeError(f"{method}: {msg['error']}")
                    return msg.get("result", {})
                if "method" in msg:
                    events.append(msg)

        await send("Page.enable")
        await send("Runtime.enable")
        await send("Network.enable")
        await send("Log.enable")
        url = pathlib.Path(HTML).as_uri()
        out["url"] = url
        await send("Page.navigate", {"url": url})
