        await send("Log.enable")
        url = pathlib.Path(HTML).as_uri()
        out["url"] = url
        await send("Page.navigate", {"url": url})
        # let the page settle
        deadline = time.time() + 4
        while time.time() < deadline:
            try:
                msg = json.loads(await asyncio.wait_for(ws.recv(), timeout=0.4))
                if "method" in msg:
                    events.append(msg)
            except asyncio.TimeoutError:
                pass

        for e in events:
            if e["method"] == "Network.requestWillBeSent":
                out["requests"].append(e["params"]["request"]["url"])
            if e["method"] in ("Network.loadingFailed", "Log.entryAdded"):
                out.setdefault("log", []).append(json.dumps(e["params"])[:300])

        probe = r"""
        (() => {
          const svg = document.querySelector('svg');
          const nodes = [...document.querySelectorAll('g.node')];
          const vis = el => { const r = el.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
          const feature = nodes.find(n => n.dataset.id === 'LT-FEATURE-001');
          const featureText = feature ? [...feature.querySelectorAll('text')].map(t => t.textContent).join(' | ') : null;
          const m = featureText && featureText.match(/(\d+)\s*\/\s*(\d+)/);
          const tasks = nodes.filter(n => /^SYS-LTF001-P\d\d$/.test(n.dataset.id));
          const edges = [...document.querySelectorAll('svg .edges path')];
          const edgeLens = edges.map(p => p.getTotalLength());
          // exercise inline JS: filter to a single task id
          const q = document.querySelector('#q');
          q.value = 'SYS-LTF001-P07';
          q.dispatchEvent(new Event('input', {bubbles: true}));
          const afterFilter = nodes.filter(n => !n.classList.contains('hidden')).map(n => n.dataset.id);
          q.value = '';
          q.dispatchEvent(new Event('input', {bubbles: true}));
          const afterReset = nodes.filter(n => !n.classList.contains('hidden')).length;
          return {
            svgPresent: !!svg,
            svgBox: svg ? {w: svg.getBoundingClientRect().width, h: svg.getBoundingClientRect().height} : null,
            nodeCount: nodes.length,
            visibleNodeCount: nodes.filter(vis).length,
            featureVisible: feature ? vis(feature) : false,
            featureText,
            featureProgress: m ? {x: +m[1], y: +m[2]} : null,
            taskCount: tasks.length,
            visibleTaskCount: tasks.filter(vis).length,
            edgeCount: edges.length,
            edgesDrawn: edgeLens.filter(l => l > 0).length,
            inlineScripts: [...document.querySelectorAll('script')].map(s => ({src: s.src || null, type: s.type || null, len: s.textContent.length})),
            externalLinks: [...document.querySelectorAll('link')].length,
            filterOnlyMatched: afterFilter,
            afterResetVisible: afterReset,
            bodyText: document.body.innerText.slice(0, 200)
          };
        })()
        """
        res = await send("Runtime.evaluate", {"expression": probe, "returnByValue": True, "awaitPromise": True})
        out["probe"] = res["result"]["value"]
        shot = await send("Page.captureScreenshot", {"format": "png", "captureBeyondViewport": True})
        import base64
        open(SHOT, "wb").write(base64.b64decode(shot["data"]))
        out["screenshot"] = SHOT
    print(json.dumps(out, ensure_ascii=False, indent=2))

